mapper.update:
update article_reviews

    status = #{status},
     reason = #{reason}

where article_id = #{articleId}

mapper.select:
SELECT ar.review_id as reviewId, ar.article_id as articleId, a.title, u.username as userName, ar.status, ar.reason, ar.created_at as createdAt, ar.reviewed_at as reviewedAt FROM article_reviews ar LEFT JOIN articles a ON ar.article_id = a.article_id LEFT JOIN users u ON a.user_id = u.user_id
AND ar.status = #{status}
ORDER BY ar.created_at DESC
